    task: trajectory.action || 'Migrated Episode',
    input: ep[1],  // trajectory
    output: ep[1],
    reward: ep[3] === 'success' ? 0.8 : 0.2,  // verdict
    success: ep[3] === 'success',
    session_id: 'migration',
    critique: ep[2] || ''  // self_reflection
  });
}

