  const start = Date.now();

  try {
    const results = await attention.hyperbolic.hierarchicalSearch(query, k);
    const duration = Date.now() - start;

    stats.queries++;
    stats.avgQueryTime = (stats.avgQueryTime * (stats.queries - 1) + duration) / stats.queries;

    return results;
