export function withTransaction<T>(
  db: Database.Database,
  operation: () => T
): T {
  const transaction = db.transaction(operation);
  try {
    return transaction();
  } catch (error) {
    // Transaction automatically rolled back
    throw new DatabaseError('Transaction failed', { cause: error });
  }
}

