  db: AgentDB,
  baseVersion: number
): DeltaSync {
  const operations = db.queryChanges(
    'SELECT * FROM change_log WHERE version > ?',
    baseVersion
  ).map(change => ({
    type: change.operation,
    ...change.data,
  }));

