// In SkillLibrary.ts
async createSkillBatch(skills: Skill[]): Promise<number[]> {
  // Batch embed all skill descriptions
  const descriptions = skills.map(s => s.description || s.name);
  const embeddings = await this.embedder.batchEmbed(descriptions);

