 * @param onlySuccessful - Filter by success flag
 * @returns Array of episodes
 * @throws ValidationError on invalid input
 */
export function searchEpisodes(
  sessionId: string,
  k: number = 10,
  onlySuccessful: boolean = false,
): Episode[] {
  try {
    // Validate all inputs
    const validatedSessionId = validateSessionId(sessionId);
    const validatedK = validateNumericRange(k, "k", 1, 100);
    const validatedSuccess = validateBoolean(
      onlySuccessful,
      "onlySuccessful",
      false,
    );

    // Build query with parameterized values
    let query = "SELECT * FROM episodes WHERE session_id = ?";
    const params: any[] = [validatedSessionId];

    if (validatedSuccess) {
      query += " AND success = ?";
      params.push(1);
    }

    query += " LIMIT ?";
    params.push(validatedK);

atedSuccess = validateBoolean(
      onlySuccessful,
      "onlySuccessful",
      false,
    );

