 */
export function searchEpisodes(
  sessionId: string,
  k: number = 10,
  onlySuccessful: boolean = false
): Episode[] {
  try {
    // Validate all inputs
    const validatedSessionId = validateSessionId(sessionId);
    const validatedK = validateNumericRange(k, 'k', 1, 100);
