  edges: Array<any>;
  stats?: any;
};

type JsBatchInsert = {
  nodes: Array<JsNode>;
  edges: Array<JsEdge>;
};

export interface GraphDatabaseConfig {
  storagePath: string;
  dimensions?: number; // Default: 384 (matches sentence-transformers models)
  distanceMetric?: 'Cosine' | 'Euclidean' | 'DotProduct' | 'Manhattan';
}

