      ? `MATCH (n {id: '${escaped}'}) DETACH DELETE n RETURN count(n) AS deleted`
      : `MATCH (n {id: '${escaped}'}) DELETE n RETURN count(n) AS deleted`;

    const result = await this.db.query(cypher);
