      await fs.writeFile(mappingsPath, JSON.stringify(mappings, null, 2));

      console.log(`[HNSWLibBackend] Index saved to ${savePath}`);
      console.log(`[HNSWLibBackend] Mappings saved to ${mappingsPath}`);
