  endSession(agentId: string): SessionStats {
    this.ensureAlive();
    const agent = this.activeSessions.get(agentId);
    if (!agent) {
      throw new Error(`No active session for agent: ${agentId}`);
    }

    // Force learn to extract patterns
    agent.forceLearn();

