  createAdapter(name: string, rank?: number): void {
    this.ensureAlive();
    if (!this.loraManager) return;

    const safeRank = Math.min(Math.max(1, rank ?? this.config.loraRank ?? 4), MAX_LORA_RANK);
    this.loraManager.create(name, {
      inputDim: this.dim,
