  attempts: number;
  successes: number;
  totalSteps: number;
  alphaSafety: number;
  betaSafety: number;
  costEma: number;
  earlyCommitWrongs: number;
}

/** KnowledgeCompiler distilled configuration entry (v0.1.6) */
export interface SolverCompiledConfig {
  maxSteps: number;
  avgSteps: number;
  observations: number;
  expectedCorrect: boolean;
  hitCount: number;
  counterexampleCount: number;
