  // ─── Session lifecycle (Phase 4) ───

  async beginSession(agentId: string): Promise<string> {
    this.ensureAlive();
    if (!this.federated) return agentId;
    this.activeSessions.set(agentId, await this.federated.beginSession(agentId));
