  recordFeedback(queryId: string, quality: number): void {
    this.ensureAlive();
    const q = Math.min(Math.max(0, quality), 1);
    const traj = this.activeTrajectories.get(queryId);
    if (!traj) return;

    if (this.sona) try { this.sona.endTrajectory(traj.id, q); } catch { /* skip */ }
