        (sum, r) => sum + (r.opsPerSec > 0 ? 500 / (r.opsPerSec / 1000) : 0),
        0
      ),
      operations: results.length * 500,
      metadata: {
        breakdown: results,
        optimalConcurrency: bestResult.concurrency,
        readWriteRatio: '70/30',
      },
    };
  }

  async teardown(): Promise<void> {
    this.backend?.close();
    this.forceGC();
  }
}

