          sum += row[j] * eigenvectors[i][j];
        }
        projected[i] = sum;
      }
      return projected;
    });

    return compressed;
  }

  /**
   * Compute mean vector
   */
  private static computeMean(matrix: number[][]): number[] {
    const n = matrix.length;
    const dim = matrix[0].length;
    const mean = new Array(dim).fill(0);

    for (const row of matrix) {
      for (let i = 0; i < dim; i++) {
        mean[i] += row[i];
      }
    }

    return mean.map(v => v / n);
  }

  /**
   * Compute covariance matrix
   */
  private static computeCovariance(matrix: number[][]): number[][] {
    const n = matrix.length;
    const dim = matrix[0].length;
    const cov: number[][] = Array.from({ length: dim }, () =>
      new Array(dim).fill(0)
    );

    for (let i = 0; i < dim; i++) {
      for (let j = 0; j <= i; j++) {
        let sum = 0;
        for (const row of matrix) {
          sum += row[i] * row[j];
        }
        cov[i][j] = cov[j][i] = sum / n;
      }
    }

    return cov;
  }

  /**
   * Power iteration for computing top eigenvectors
   */
  private static powerIteration(
    matrix: number[][],
    k: number,
    iterations: number = 100
  ): number[][] {
    const dim = matrix.length;
    const eigenvectors: number[][] = [];

    for (let i = 0; i < k; i++) {
      // Random initialization
      let v = new Array(dim).fill(0).map(() => Math.random() - 0.5);

      // Power iteration
      for (let iter = 0; iter < iterations; iter++) {
        // Multiply by matrix
        const newV = new Array(dim).fill(0);
        for (let r = 0; r < dim; r++) {
          for (let c = 0; c < dim; c++) {
            newV[r] += matrix[r][c] * v[c];
          }
        }

        // Orthogonalize against previous eigenvectors
        for (const prev of eigenvectors) {
          let dot = 0;
          for (let j = 0; j < dim; j++) {
            dot += newV[j] * prev[j];
          }
          for (let j = 0; j < dim; j++) {
            newV[j] -= dot * prev[j];
          }
        }

        // Normalize
        let norm = 0;
        for (const val of newV) {
          norm += val * val;
        }
        norm = Math.sqrt(norm);

        if (norm < 1e-10) break;

        v = newV.map(val => val / norm);
      }

      eigenvectors.push(v);
    }

    return eigenvectors;
  }
}

