    for (let c = 0; c < this.config.numCentroids; c++) {
      const centroid = this.codebook.centroids[centroidOffset + c];
      const dist = this.squaredDistance(subvector, centroid);
      if (dist < minDist) {
        minDist = dist;
        minIdx = c;
      }
    }

    codes[s] = minIdx;
  }

  return { codes, norm };
