    const attended = this.aggregateAttendedOutputs(
      query,
      contextResults.map(r => r.attended),
      Object.values(contextWeights),
      aggregation
    );

    const executionTimeMs = performance.now() - startTime;

    return {
      scores: allScores,
      attended,
      contextWeights,
      executionTimeMs
