  } else if (groupBy === 'session') {
    groupedMetrics = this.db.prepare(`
      SELECT
        session_id as group_key,
        COUNT(*) as count,
        AVG(reward) as avg_reward,
        AVG(CASE WHEN success = 1 THEN 1.0 ELSE 0.0 END) as success_rate
      FROM learning_experiences
      ${whereClause}
      GROUP BY session_id
      ORDER BY count DESC
