    `).all(...params) as any[];
  }

  // Trend analysis
  let trends: any[] = [];
  if (includeTrends) {
    trends = this.db.prepare(`
      SELECT
        DATE(timestamp / 1000, 'unixepoch') as date,
        COUNT(*) as count,
