  /**
   * Prune old or low-confidence edges
   */
  private async pruneEdges(): Promise<number> {
    const maxAgeMs = this.config.edgeMaxAgeDays * 24 * 60 * 60 * 1000;
    const cutoffTime = Date.now() / 1000 - maxAgeMs / 1000;

    const result = this.db.prepare(`
