      return `${i + 1}. Approach (reward ${ep.reward.toFixed(2)}): ${approach}...`;
    })
    .join('\n');

  const result = `Successful strategies:\n${strategies}`;

  // Cache the result
  this.queryCache.set(cacheKey, result);
  return result;
}

