    SELECT
      task,
      COUNT(*) as attempt_count,
      AVG(reward) as avg_reward,
      AVG(success) as success_rate,
      AVG(latency_ms) as avg_latency,
      MAX(id) as latest_episode_id,
      GROUP_CONCAT(id) as episode_ids
    FROM episodes
