  private async loadSchemas(): Promise<void> {
    const { SCHEMA_SQL, FRONTIER_SCHEMA_SQL } = await import('../schemas/inline.js');
    if (SCHEMA_SQL) this.db.exec(SCHEMA_SQL);
    if (FRONTIER_SCHEMA_SQL) this.db.exec(FRONTIER_SCHEMA_SQL);
