export function customSecurityHeaders(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  // Permissions Policy (Feature Policy)
  res.setHeader(
    'Permissions-Policy',
    [
      'camera=()',
      'microphone=()',
      'geolocation=()',
      'payment=()',
      'usb=()',
      'magnetometer=()',
      'gyroscope=()',
      'accelerometer=()',
    ].join(', ')
  );

  // Expect-CT header (Certificate Transparency)
  res.setHeader(
    'Expect-CT',
    'max-age=86400, enforce'
  );

  // X-Permitted-Cross-Domain-Policies
  res.setHeader('X-Permitted-Cross-Domain-Policies', 'none');

  // Cache-Control for sensitive endpoints
  if (req.path.includes('/auth') || req.path.includes('/api')) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
  }

  next();
}

/**
 * Remove sensitive headers
 */
export function removeSensitiveHeaders(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  // Remove headers that might leak server information
  res.removeHeader('X-Powered-By');
  res.removeHeader('Server');

  next();
}

/**
 * HSTS preload header (for production)
 */
export function hstsPreload(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  if (process.env.NODE_ENV === 'production') {
    res.setHeader(
      'Strict-Transport-Security',
      'max-age=31536000; includeSubDomains; preload'
    );
  }

  next();
}

/**
 * Security headers for API responses
 */
export function apiSecurityHeaders(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  // JSON responses only
  res.setHeader('Content-Type', 'application/json; charset=utf-8');

  // No caching for API responses
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  // Prevent MIME sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  next();
}

/**
 * Combined security middleware
 */
export function applySecurity(options: {
  cors?: boolean;
  corsOrigins?: string[];
  hsts?: boolean;
  csp?: boolean;
} = {}) {
  const {
    cors = true,
    corsOrigins = ['http://localhost:3000'],
    hsts = true,
    csp = true,
  } = options;

  const middlewares: Array<(req: Request, res: Response, next: NextFunction) => void> = [];

  // Remove sensitive headers
  middlewares.push(removeSensitiveHeaders);

  // Apply Helmet security headers
  if (csp) {
    middlewares.push(securityHeaders);
  }

  // Apply custom security headers
  middlewares.push(customSecurityHeaders);

  // Apply HSTS preload
  if (hsts) {
    middlewares.push(hstsPreload);
  }

  // Apply CORS
  if (cors) {
    middlewares.push(configureCORS({ allowedOrigins: corsOrigins }));
  }

  return (req: Request, res: Response, next: NextFunction): void => {
    let index = 0;

    const runNext = (): void => {
      if (index >= middlewares.length) {
        next();
        return;
      }

      const middleware = middlewares[index++];
      middleware(req, res, runNext);
    };

    runNext();
  };
}

/**
 * Development-only CORS (allow all)
 */
export function developmentCORS(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  if (process.env.NODE_ENV === 'development') {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', '*');
    res.setHeader('Access-Control-Allow-Headers', '*');

    if (req.method === 'OPTIONS') {
      res.status(204).send();
      return;
    }
  }

  next();
}

