/**
 * Create span attributes from operation context
 */
export function createSpanAttributes(context: {
  operation?: string;
  table?: string;
  filters?: Record<string, any>;
  limit?: number;
  offset?: number;
}): Record<string, any> {
  const attributes: Record<string, any> = {};

