   */
  private dequantizeStored(
    quantized: QuantizedVector | PQEncodedVector
  ): Float32Array {
    if (this.config.quantizationType === 'product') {
      if (!this.productQuantizer) {
        throw new Error('ProductQuantizer not initialized');
