    this.lastFailureTime = Date.now();

    if (this.failures >= this.maxFailures) {
      this.state = 'open';
      console.error(`[CircuitBreaker] Opened after ${this.failures} failures`);
    }
  }

  /**
   * Get circuit breaker status
