        // Extract encoding strength from the result
        for (let k = 0; k < numKeys; k++) {
          const hopDistance = hopDistances[q]?.[k] || 0;
          const scale = 1.0 / (1.0 + hopDistance);
          hopEncodings[q * numKeys + k] = scale;

          // Apply rotary-like scaling to queries
