      const invSum = runningSum[qi] > 1e-8 ? 1.0 / runningSum[qi] : 0;
      for (let d = 0; d < dim; d++) {
        output[i * dim + d] = accumulatedOutput[qi * dim + d] * invSum;
      }
    }
  }

  const durationMs = Date.now() - startTime;
  logPerformance({
