  private async initializeLogDirectory(): Promise<void> {
    try {
      await fs.mkdir(this.config.logDirectory, { recursive: true });
    } catch (error) {
      console.error('[Audit Logger] Failed to create log directory:', error);
    }
  }

  /**
   * Get current log file path
