// ============================================================================
// LRU Cache Implementation with O(1) Operations
// ============================================================================

/**
 * Doubly-linked list node for LRU cache
 */
interface CacheNode {
  key: string;
  value: Float32Array;
  prev: CacheNode | null;
  next: CacheNode | null;
}

/**
 * LRU Cache with O(1) get/put operations using doubly-linked list + hash map
 */
class LRUCache {
  private capacity: number;
  private map: Map<string, CacheNode> = new Map();
  private head: CacheNode | null = null;
  private tail: CacheNode | null = null;

  // Statistics
  private _hits = 0;
  private _misses = 0;
  private trackStats: boolean;

  constructor(capacity: number, trackStats = true) {
    // Enforce maximum cache size for security
    this.capacity = Math.min(Math.max(1, capacity), MAX_CACHE_SIZE);
    this.trackStats = trackStats;
  }

  /**
   * Get value from cache - O(1)
   */
  get(key: string): Float32Array | undefined {
    const node = this.map.get(key);
    if (!node) {
      if (this.trackStats) this._misses++;
      return undefined;
    }

    if (this.trackStats) this._hits++;

    // Move to front (most recently used)
    this.moveToFront(node);
    return node.value;
  }

  /**
   * Put value in cache - O(1)
   */
  put(key: string, value: Float32Array): void {
    const existingNode = this.map.get(key);

    if (existingNode) {
      // Update existing node and move to front
      existingNode.value = value;
      this.moveToFront(existingNode);
      return;
    }

    // Create new node
    const newNode: CacheNode = {
      key,
      value,
      prev: null,
      next: this.head,
    };

    // Add to front
    if (this.head) {
      this.head.prev = newNode;
    }
    this.head = newNode;

    if (!this.tail) {
      this.tail = newNode;
    }

    this.map.set(key, newNode);

    // Evict if over capacity
    if (this.map.size > this.capacity) {
      this.evictLRU();
    }
  }

  /**
   * Check if key exists - O(1)
   */
  has(key: string): boolean {
    return this.map.has(key);
  }

  /**
   * Delete key from cache - O(1)
   */
  delete(key: string): boolean {
    const node = this.map.get(key);
    if (!node) return false;

    this.removeNode(node);
    this.map.delete(key);
    return true;
  }

  /**
   * Clear all entries
   */
  clear(): void {
    this.map.clear();
    this.head = null;
    this.tail = null;
    this._hits = 0;
    this._misses = 0;
  }

  /**
   * Get current size
   */
  get size(): number {
    return this.map.size;
  }

  /**
   * Get cache statistics
   */
  get stats(): { hits: number; misses: number; hitRate: number; size: number; maxSize: number } {
    const total = this._hits + this._misses;
    return {
      hits: this._hits,
      misses: this._misses,
      hitRate: total > 0 ? this._hits / total : 0,
      size: this.map.size,
      maxSize: this.capacity,
    };
  }

  /**
   * Move node to front of list (most recently used)
   */
  private moveToFront(node: CacheNode): void {
    if (node === this.head) return;

    // Remove from current position
    this.removeNode(node);

    // Add to front
    node.prev = null;
    node.next = this.head;
    if (this.head) {
      this.head.prev = node;
    }
    this.head = node;

    if (!this.tail) {
      this.tail = node;
    }
  }

  /**
   * Remove node from list
   */
  private removeNode(node: CacheNode): void {
    if (node.prev) {
      node.prev.next = node.next;
    } else {
      this.head = node.next;
    }

    if (node.next) {
      node.next.prev = node.prev;
    } else {
      this.tail = node.prev;
    }
  }

  /**
   * Evict least recently used entry
   */
  private evictLRU(): void {
    if (!this.tail) return;

    const lruKey = this.tail.key;
    this.removeNode(this.tail);
    this.map.delete(lruKey);
  }
}

