  let dot0 = 0,
    dot1 = 0,
    dot2 = 0,
    dot3 = 0,
    dot4 = 0,
    dot5 = 0,
    dot6 = 0,
    dot7 = 0;

  const loopEnd = len - (len % 8);

  for (let i = 0; i < loopEnd; i += 8) {
    dot0 += a[i] * b[i];
    dot1 += a[i + 1] * b[i + 1];
    dot2 += a[i + 2] * b[i + 2];
    dot3 += a[i + 3] * b[i + 3];
    dot4 += a[i + 4] * b[i + 4];
    dot5 += a[i + 5] * b[i + 5];
    dot6 += a[i + 6] * b[i + 6];
