    v[i + 1] *= invNorm;
    v[i + 2] *= invNorm;
    v[i + 3] *= invNorm;
    v[i + 4] *= invNorm;
    v[i + 5] *= invNorm;
    v[i + 6] *= invNorm;
    v[i + 7] *= invNorm;
  }

  for (let i = loopEnd; i < len; i++) {
    v[i] *= invNorm;
  }

  return v;
