         dValue[dVOffset + d + 4] += aWeight * dOutput[dOOffset + d + 4];
         dValue[dVOffset + d + 5] += aWeight * dOutput[dOOffset + d + 5];
         dValue[dVOffset + d + 6] += aWeight * dOutput[dOOffset + d + 6];
         dValue[dVOffset + d + 7] += aWeight * dOutput[dOOffset + d + 7];
