export function shouldUseNativePackage(packageName: string): boolean {
  const alphaPackages = [
    '@ruvector/gnn',
    '@ruvector/attention',
    'agentdb-cli', // Use programmatic API instead
  ];

  return !alphaPackages.some((pkg) => packageName.includes(pkg));
