// Find all paths between two nodes
function findAllPaths(source, target, visited = new Set()) {
 if (source === target) return [[source]];

 visited.add(source);
 const paths = [];

 const outEdges = graphState.edges.filter(e => e.cause === source);
 outEdges.forEach(edge => {
